function exportExcel(m,setFilter=null){const escXml=v=>String(v??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");const xml='<?xml version="1.0" encoding="UTF-8"?><?mso-application progid="Excel.Sheet"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">'+reportSections(m,setFilter).map(([name,rows])=>'<Worksheet ss:Name="'+escXml(name)+'"><Table>'+rows.map(row=>'<Row>'+row.map(v=>'<Cell><Data ss:Type="'+(typeof v==="number"?"Number":"String")+'">'+escXml(v)+'</Data></Cell>').join("")+'</Row>').join("")+'</Table></Worksheet>').join("")+'</Workbook>';downloadText("volley-scout-"+m.id.slice(0,8)+(setFilter===null?"":"-set-"+setFilter)+".xls",xml,"application/vnd.ms-excel;charset=utf-8")}
