const total=metrics(actions);
const select='<div class="card"><label>Filtro set</label><select id="stats-set"><option value="all">Tutti i set</option>'+sets.map(n=>'<option value="'+n+'" '+(statsSet===String(n)?"selected":"")+'>Set '+n+'</option>').join("")+'</select><p class="muted">Statistiche calcolate su '+actions.length+' azioni registrate</p></div>';
