const fundamentalsHtml=fundamentals.map(f=>{const arr=by(actions,f),rated=valid(arr);return '<div class="card"><h3>'+f+' · '+arr.length+' azioni</h3><p class="muted">'+quality[f].map(q=>q[0]+' '+count(actions,f,q[0])).join(' · ')+(f==="Difesa"?' · Freeball '+count(actions,f,"FB"):'')+'</p><div class="grid"><div class="item small"><b>'+percent(positive(rated),rated.length)+'</b><br>Valutazioni # e +</div><div class="item small"><b>'+percent(count(actions,f,"="),rated.length)+'</b><br>Errori diretti</div></div></div>'}).join("");
const rallyGroups=new Map();for(const a of actions){const k=a.matchId+"|"+a.set+"|"+a.rally;if(!rallyGroups.has(k))rallyGroups.set(k,[]);rallyGroups.get(k).push(a)}
const pairs=[];for(const group of rallyGroups.values()){group.sort((a,b)=>a.at-b.at);for(let i=0;i<group.length;i++){const a=group[i];if(a.fundamental!=="Alzata"||!["#","+","!","-"].includes(a.quality))continue;for(let j=i+1;j<group.length;j++){if(group[j].fundamental==="Alzata")break;if(group[j].fundamental==="Attacco"){pairs.push({set:a,attack:group[j]});break}}}}
