const breakdown=(label,arr)=>{const mm=metrics(arr),rec=by(arr,"Ricezione"),set=by(arr,"Alzata"),atk=by(arr,"Attacco");return '<div class="item small" style="margin-bottom:8px"><b>'+label+'</b> · '+arr.length+' azioni<div class="grid" style="margin-top:8px"><span>Attacco: '+mm.kills+'/'+mm.atk+' · '+mm.atkPct+' punti · '+mm.atkEff+' eff.</span><span>Ricezione #/+: '+mm.recPos+'</span><span>Alzate #/+: '+mm.setPos+'</span><span>Punti individuali: '+mm.points+' · Errori: '+mm.errors+'</span></div></div>'};
