const playerRanking='<div class="card"><h3>Graduatorie individuali</h3>'+[['Punti', 'points'],['Errori','errors'],['Attacco punto %','atkPct'],['Efficienza attacco','atkEff']].map(([label,key])=>{const ranked=ranking.filter(p=>key==="points"||key==="errors"||p.atk>0).slice().sort((a,b)=>{const number=v=>typeof v==="number"?v:parseFloat(String(v).replace(",","."))||0;return number(b[key])-number(a[key])});return '<h4>'+label+'</h4><p class="small">'+ranked.slice(0,5).map((p,i)=>(i+1)+'. #'+esc(p.number)+' '+esc(p.name)+' — '+p[key]).join('<br>')+'</p>'}).join("")+'</div>';
const chainRows=[];
for(const group of rallyGroups.values()){const g=group.slice().sort((a,b)=>a.at-b.at);for(let i=0;i<g.length;i++){if(g[i].fundamental!=="Attacco")continue;let setIdx=-1,recIdx=-1;for(let j=i-1;j>=0;j--){if(g[j].fundamental==="Attacco")break;if(setIdx<0&&g[j].fundamental==="Alzata")setIdx=j;if(g[j].fundamental==="Ricezione"){recIdx=j;break}}if(setIdx>=0&&recIdx>=0&&recIdx<setIdx&&["#","+","!","-","="].includes(g[recIdx].quality))chainRows.push({rec:g[recIdx],set:g[setIdx],atk:g[i]})}}
const receptionChain='<div class="card"><h3>Ricezione → Alzata → Attacco</h3><p class="muted">Sequenze complete registrate nello stesso scambio: '+chainRows.length+'</p>'+["#","+","!","-","="].map(q=>{const rr=chainRows.filter(x=>x.rec.quality===q),kills=rr.filter(x=>x.atk.quality==="#").length,errs=rr.filter(x=>["=","-"].includes(x.atk.quality)).length;return '<div class="item small" style="margin-bottom:6px"><b>Ricezione '+q+'</b> · '+rr.length+' attacchi · '+kills+' punti · '+percent(kills,rr.length)+' punto · '+efficiency(kills,errs,rr.length)+' eff.</div>'}).join("")+'<p class="muted small">Escluse le sequenze incomplete. Il collegamento è ricostruito dall’ordine delle azioni e va interpretato come indicativo.</p></div>';
const recPerfect=actions.filter(a=>a.fundamental==="Ricezione"&&a.quality==="#").length,recTotal=actions.filter(a=>a.fundamental==="Ricezione").length;const extraRec='<div class="card"><h3>Precisione ricezione</h3><p>Perfette: '+recPerfect+'/'+recTotal+' · '+percent(recPerfect,recTotal)+'</p><p>Positive (# e +): '+total.recPos+'</p></div>';const seconds=actions.filter(a=>a.attackType==="seconda-intenzione"),secondKills=seconds.filter(a=>a.quality==="#").length,secondErrors=seconds.filter(a=>a.quality==="="||a.quality==="-").length;const perPlayerSeconds=[...players.values()].map(p=>{const arr=seconds.filter(a=>a.playerId===p.id);return {p,arr,k:arr.filter(a=>a.quality==="#").length}}).filter(x=>x.arr.length);const secondStats='<div class="card"><h3>Seconde intenzioni</h3><p>'+seconds.length+' tentativi · '+secondKills+' punti · '+percent(secondKills,seconds.length)+' punto · '+efficiency(secondKills,secondErrors,seconds.length)+' efficienza</p>'+perPlayerSeconds.map(x=>'<p class="small">#'+esc(x.p.number)+' '+esc(x.p.name)+': '+x.k+'/'+x.arr.length+' punti · '+percent(x.k,x.arr.length)+'</p>').join("")+'</div>';return '<h1 class="title">Statistiche · Beta 20</h1>'+select+extraRec+secondStats+overview+rankingHtml+playerRanking+setComparison+rotationComparison+receptionChain+linked+details+'<h2>Fondamentali</h2>'+fundamentalsHtml
